  WORD32 i = 0;
  FLOAT32 result = 0.0f;
  CHAR8 line[1024];
  pCHAR8 retval;
  retval = fgets(line, sizeof(line), fp);
  if (retval) {
    pCHAR8 c = line;
    while ((line[0] == '#' || line[0] == '\n') && (retval != NULL)) {
      retval = fgets(line, sizeof(line), fp);
    }
    // FIX: Add bounds checking
    while (i < sizeof(line) - 1 && line[i] != ':' && line[i] != '\0') {
      c++;
      i++;
    }
    // FIX: Validate ':' was found
    if (i < sizeof(line) - 1 && line[i] == ':') {
      c++;
      result = (FLOAT32)atof(c);
    }
  }
  return result;
}
```
